use xiom.io;
type Account {
  owner: Str;
  balance: Int;
}

requires { amount > 0; }
fn deposit(acc: &mut Account, amount: Int) {
  acc.balance = acc.balance + amount;
}

requires { amount > 0; }
requires { acc.balance >= amount; }
fn withdraw(acc: &mut Account, amount: Int) -> Bool {
  acc.balance = acc.balance - amount;
  true
}

fn main() -> Int {
  let mut acc = Account{ owner: "Alice", balance: 0 };
  deposit(&mut acc, 500);
  withdraw(&mut acc, 200);
  io.println(acc.balance.to_str());
  return 0;
}
